+            // Proof that combiner_has_inv holds in post
+            assert forall |i: nat| #[trigger] post.combiner_has(i) implies
+                post.client_waiting(i)
+                && post.slots.index(i)
+                && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
+                && !post.request_stored(i) by {
+                // The combiner state is unchanged, so if it had something before, it still has it
+                assert(pre.combiner_has(i));
+                assert(pre.client_waiting(i));
+                assert(pre.slots.index(i));
+                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
+                assert(!pre.request_stored(i));
+                // These properties carry over to post
+                assert(post.client_waiting(i));
+                assert(post.slots.index(i));
+                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
+                assert(!post.request_stored(i));
+            }
+        }
+
+        ///// Combiner transitions
+
+        transition!{
+            combiner_recv() {
+                require(pre.combiner.is_Collecting());
+                let j = pre.combiner.get_Collecting_elems().len();
+                require(0 <= j && j < pre.num_clients);
+
+                // Observe that the slot has been set to 'true'
+                have slots >= [j => true];
+
+                // Withdraw a request
+                withdraw requests -= [j => let request] by {
+                    assert(pre.valid_idx(j));
+                    assert(pre.client_waiting(j));
+                    assert(pre.request_stored(j));
+                };
+
+                // Update combiner's local state to remember we withdrew a request with this ID
+                update combiner = Combiner::Collecting{
+                    elems: pre.combiner.get_Collecting_elems().push(Option::Some(request.rid)),
+                };
+            }
+        }
+
+        #[inductive(combiner_recv)]
+        fn combiner_recv_inductive(pre: Self, post: Self) {
+            let j = pre.combiner.get_Collecting_elems().len();
+            
+            // Proof that not_waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
+                !post.slots.index(i) by {
+                // Properties for clients are unchanged
+                assert(pre.valid_idx(i));
+                assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
+                assert(pre.slots.index(i) == post.slots.index(i));
+                // Since not_waiting_inv holds for pre, it holds for post
+                assert(!pre.slots.index(i));
+            }
+            
+            // Proof that waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
+                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
+                if i == j {
+                    // Client j is waiting and now the combiner has its request
+                    assert(post.combiner_has(i));
+                } else {
+                    // Other waiting clients are unchanged
+                    assert(pre.client_waiting(i) == post.client_waiting(i));
+                    assert(pre.request_stored(i) == post.request_stored(i));
+                    assert(pre.response_stored(i) == post.response_stored(i));
+                    // For combiner_has, only position j changed
+                    if pre.combiner_has(i) {
+                        assert(post.combiner_has(i));
+                    }
+                    // Since waiting_inv holds for pre, it holds for post
+                    assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
+                }
+            }
+            
+            // Proof that request_stored_inv holds in post
+            assert forall |i: nat| #[trigger] post.request_stored(i) implies
+                post.client_waiting(i)
+                && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
+                && post.slots.index(i) by {
+                assert(i != j); // Because we just withdrew the request for j
+                // Properties for other stored requests are unchanged
+                assert(pre.request_stored(i));
+                assert(pre.client_waiting(i));
+                assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
+                assert(pre.slots.index(i));
+                // These properties carry over to post
+                assert(post.client_waiting(i));
+                assert(post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid());
+                assert(post.slots.index(i));
+            }
+            
+            // Proof that combiner_has_inv holds in post
+            assert forall |i: nat| #[trigger] post.combiner_has(i) implies
+                post.client_waiting(i)
+                && post.slots.index(i)
+                && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
+                && !post.request_stored(i) by {
+                if i == j {
+                    // This is the element we just added to combiner
+                    assert(post.combiner_has(i));
+                    assert(post.client_waiting(i));
+                    assert(post.slots.index(i)); // Required by have clause
+                    assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
+                    // The request was just withdrawn, so it's not stored anymore
+                    assert(!post.request_stored(i));
+                } else {
+                    // Other elements in combiner are unchanged
+                    assert(pre.combiner_has(i) == post.combiner_has(i));
+                    if pre.combiner_has(i) {
+                        assert(pre.client_waiting(i));
+                        assert(pre.slots.index(i));
+                        assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
+                        assert(!pre.request_stored(i));
+                        // These properties carry over to post
+                        assert(post.client_waiting(i));
+                        assert(post.slots.index(i));
+                        assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
+                        assert(!post.request_stored(i));
+                    }
+                }
+            }
+        }
+
+        transition!{
+            combiner_skip() {
+                require(pre.combiner.is_Collecting());
+                let j = pre.combiner.get_Collecting_elems().len();
+                require(0 <= j && j < pre.num_clients);
+
+                // In practice, this happens when slot j is set to false, so we could add this:
+                //    have slots >= [j => false];
+                // but it's not necessary
+
+                // Update combiner's local state to remember that we didn't withdraw
+                // anything here.
+                update combiner = Combiner::Collecting{
+                    elems: pre.combiner.get_Collecting_elems().push(Option::None),
+                };
+            }
+        }
+
+        #[inductive(combiner_skip)]
+        fn combiner_skip_inductive(pre: Self, post: Self) {
+            let j = pre.combiner.get_Collecting_elems().len();
+            
+            // Proof that not_waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
+                !post.slots.index(i) by {
+                // Properties for clients are unchanged
+                assert(pre.valid_idx(i));
+                assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
+                assert(pre.slots.index(i) == post.slots.index(i));
+                // Since not_waiting_inv holds for pre, it holds for post
+                assert(!pre.slots.index(i));
+            }
+            
+            // Proof that waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
+                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
+                // Client states are unchanged
+                assert(pre.client_waiting(i) == post.client_waiting(i));
+                assert(pre.request_stored(i) == post.request_stored(i));
+                assert(pre.response_stored(i) == post.response_stored(i));
+                // For combiner_has, only position j changed (added None)
+                if pre.combiner_has(i) {
+                    assert(post.combiner_has(i));
+                } else if i == j {
+                    // Position j now has None, so combiner doesn't have it
+                    assert(!post.combiner_has(i));
+                    // But waiting_inv must still hold, so client must have request or response stored
+                    assert(pre.client_waiting(i));
+                    assert(pre.request_stored(i) || pre.response_stored(i));
+                    assert(post.request_stored(i) || post.response_stored(i));
+                } else {
+                    assert(!pre.combiner_has(i));
+                    assert(!post.combiner_has(i));
+                }
+                // Since waiting_inv holds for pre, it holds for post
+                assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
+            }
+            
+            // Other invariants are unchanged since no requests/responses were modified
+        }
+
+        transition!{
+            combiner_go_to_responding() {
+                require(pre.combiner.is_Collecting());
+                require(pre.combiner.get_Collecting_elems().len() == pre.num_clients);
+                update combiner = Combiner::Responding{
+                    elems: pre.combiner.get_Collecting_elems(),
+                    idx: 0,
+                };
+            }
+        }
+
+        transition!{
+            combiner_send(response: Response, cur_slot: bool) {
+                require(pre.combiner.is_Responding());
+                let j = pre.combiner.get_Responding_idx();
+                require(0 <= j && j < pre.num_clients);
+                let response_opt = pre.combiner.get_Responding_elems().index(j as int);
+
+                // The response we return has to have the right request ID
+                require(response_opt == Option::Some(response.rid));
+
+                // Set the slot back to false
+                remove slots -= [j => cur_slot];
+                add    slots += [j => false];
+
+                // Update the combiner's local state
+                update combiner = Combiner::Responding{
+                    elems: pre.combiner.get_Responding_elems(),
+                    idx: j + 1,
+                };
+
+                deposit responses += [j => response] by {
+                    assert(pre.valid_idx(j));
+                    assert(pre.combiner_has(j));
+                    assert(!pre.response_stored(j));
+                };
+            }
+        }
+
+        #[inductive(combiner_send)]
+        fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
+            let j = pre.combiner.get_Responding_idx();
+            
+            // Proof that not_waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
+                !post.slots.index(i) by {
+                if i == j {
+                    // For client j, we explicitly set the slot to false
+                    assert(post.slots.index(i) == false);
+                } else {
+                    // For other clients, properties are unchanged
+                    assert(pre.valid_idx(i));
+                    assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
+                    assert(pre.slots.index(i) == post.slots.index(i));
+                    // Since not_waiting_inv holds for pre, it holds for post
+                    assert(!pre.slots.index(i));
+                }
+            }
+            
+            // Proof that waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
+                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
+                if i == j {
+                    // Client j is waiting and we just deposited a response for it
+                    assert(post.response_stored(i));
+                } else {
+                    // Other waiting clients are unchanged
+                    assert(pre.client_waiting(i) == post.client_waiting(i));
+                    assert(pre.request_stored(i) == post.request_stored(i));
+                    assert(pre.response_stored(i) == post.response_stored(i));
+                    assert(pre.combiner_has(i) == post.combiner_has(i));
+                    // Since waiting_inv holds for pre, it holds for post
+                    assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
+                }
+            }
+            
+            // Proof that response_stored_inv holds in post
+            assert forall |i: nat| #[trigger] post.response_stored(i) implies
+                post.client_waiting(i)
+                && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
+                && !post.slots.index(i) by {
+                if i == j {
+                    // This is the newly stored response
+                    assert(post.client_waiting(i));
+                    assert(post.responses.index(i).rid == response.rid);
+                    // From the precondition: response_opt == Option::Some(response.rid)
+                    // And from combiner_has_inv in pre: pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid()
+                    // So: response.rid == pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid()
+                    assert(post.clients.index(i).get_Waiting_rid() == response.rid);
+                    assert(post.slots.index(i) == false); // We just set it to false
+                } else {
+                    // Other stored responses are unchanged
+                    assert(pre.response_stored(i));
+                    assert(pre.client_waiting(i));
+                    assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
+                    assert(!pre.slots.index(i));
+                    // These properties carry over to post
+                    assert(post.client_waiting(i));
+                    assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
+                    assert(!post.slots.index(i));
+                }
+            }
+            
+            // Proof that combiner_has_inv holds in post
+            assert forall |i: nat| #[trigger] post.combiner_has(i) implies
+                post.client_waiting(i)
+                && post.slots.index(i)
+                && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
+                && !post.request_stored(i) by {
+                // Only positions >= idx are in combiner, and we incremented idx
+                assert(post.combiner.get_Responding_idx() == j + 1);
+                // So if post.combiner_has(i), then i >= j + 1, which means i != j
+                assert(i != j);
+                // For i != j, the combiner state for i is unchanged
+                assert(pre.combiner_has(i));
+                assert(pre.client_waiting(i));
+                assert(pre.slots.index(i));
+                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
+                assert(!pre.request_stored(i));
+                // These properties carry over to post
+                assert(post.client_waiting(i));
+                assert(post.slots.index(i));
+                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
+                assert(!post.request_stored(i));
+            }
+        }
+
+        transition!{
+            combiner_send_skip() {
+                require(pre.combiner.is_Responding());
+                let j = pre.combiner.get_Responding_idx();
+                require(0 <= j && j < pre.num_clients);
+                let response_opt = pre.combiner.get_Responding_elems().index(j as int);
+
+                // The response we return has to have the right request ID
+                require(equal(response_opt, Option::None));
+
+                // Update the combiner's local state
+                update combiner = Combiner::Responding{
+                    elems: pre.combiner.get_Responding_elems(),
+                    idx: j + 1,
+                };
+            }
+        }
+
+        #[inductive(combiner_send_skip)]
+        fn combiner_send_skip_inductive(pre: Self, post: Self) {
+            let j = pre.combiner.get_Responding_idx();
+            
+            // Proof that not_waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
+                !post.slots.index(i) by {
+                // No changes to clients or slots
+                assert(pre.valid_idx(i));
+                assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
+                assert(pre.slots.index(i) == post.slots.index(i));
+                // Since not_waiting_inv holds for pre, it holds for post
+                assert(!pre.slots.index(i));
+            }
+            
+            // Proof that waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
+                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
+                // Client states are unchanged
+                assert(pre.client_waiting(i) == post.client_waiting(i));
+                assert(pre.request_stored(i) == post.request_stored(i));
+                assert(pre.response_stored(i) == post.response_stored(i));
+                // For combiner_has, only the indexing changed (idx incremented)
+                if pre.combiner_has(i) {
+                    // If i was in combiner before, check if it's still in combiner after
+                    match pre.combiner {
+                        Combiner::Responding{elems, idx} => {
+                            if i >= idx && i < elems.len() && elems.index(i as int).is_Some() {
+                                // i was in combiner before
+                                if i >= idx + 1 {
+                                    // i is still in combiner after
+                                    assert(post.combiner_has(i));
+                                } else {
+                                    // i is no longer in combiner (i == idx)
+                                    assert(i == idx);
+                                    assert(!post.combiner_has(i));
+                                    // But waiting_inv must still hold, so client must have request or response stored
+                                    assert(pre.client_waiting(i));
+                                    assert(pre.request_stored(i) || pre.response_stored(i));
+                                    assert(post.request_stored(i) || post.response_stored(i));
+                                }
+                            }
+                        }
+                        _ => {}
+                    }
+                }
+                // Since waiting_inv holds for pre, it holds for post
+                assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
+            }
+            
+            // Other invariants are unchanged since no requests/responses were modified
+        }
+
+        #[inductive(combiner_go_to_responding)]
+        fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
+            // Proof that not_waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
+                !post.slots.index(i) by {
+                // No changes to clients or slots
+                assert(pre.valid_idx(i));
+                assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
+                assert(pre.slots.index(i) == post.slots.index(i));
+                // Since not_waiting_inv holds for pre, it holds for post
+                assert(!pre.slots.index(i));
+            }
+            
+            // Proof that waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
+                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
+                // Client states are unchanged
+                assert(pre.client_waiting(i) == post.client_waiting(i));
+                assert(pre.request_stored(i) == post.request_stored(i));
+                assert(pre.response_stored(i) == post.response_stored(i));
+                // The combiner state changed from Collecting to Responding with idx=0
+                // So now combiner_has(i) means i >= 0 and elems[i].is_Some(), which is just elems[i].is_Some()
+                // This should be equivalent to the previous combiner_has for Collecting
+                assert(pre.combiner_has(i) == post.combiner_has(i));
+                // Since waiting_inv holds for pre, it holds for post
+                assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
+            }
+            
+            // Other invariants are unchanged since no requests/responses were modified
+        }
+
+        transition!{
+            combiner_go_to_collecting() {
+                require(pre.combiner.is_Responding());
+                require(pre.combiner.get_Responding_idx() == pre.num_clients);
+                update combiner = Combiner::Collecting{ elems: Seq::empty() };
+            }
+        }
+
+        #[inductive(combiner_go_to_collecting)]
+        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
+            // Proof that not_waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
+                !post.slots.index(i) by {
+                // No changes to clients or slots
+                assert(pre.valid_idx(i));
+                assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
+                assert(pre.slots.index(i) == post.slots.index(i));
+                // Since not_waiting_inv holds for pre, it holds for post
+                assert(!pre.slots.index(i));
+            }
+            
+            // Proof that waiting_inv holds in post
+            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
+                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
+                // Client states are unchanged
+                assert(pre.client_waiting(i) == post.client_waiting(i));
+                assert(pre.request_stored(i) == post.request_stored(i));
+                assert(pre.response_stored(i) == post.response_stored(i));
+                // The combiner state changed from Responding to Collecting with empty elems
+                // So now combiner_has(i) is always false
+                assert(!post.combiner_has(i));
+                // Since waiting_inv holds for pre, and combiner_has(i) went from possibly true to false,
+                // we need to ensure request_stored(i) || response_stored(i) still holds
+                assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
+                // If pre.combiner_has(i) was true, we need to show post.request_stored(i) || post.response_stored(i)
+                // But this should follow from the invariants and the fact that we've processed all elements
+                assert(post.request_stored(i) || post.response_stored(i));
+            }
+            
+            // Other invariants are unchanged since no requests/responses were modified
+        }
+
+    }
+}
+
+fn main() {}
