#[inductive(combiner_send)]
fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
    let j = pre.combiner.get_Responding_idx();

    // Proof that not_waiting_inv holds in post
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
        !post.slots.index(i) by {
        if i == j {
            // For client j, we explicitly set the slot to false
            assert(post.slots.index(i) == false);
        } else {
            // For other clients, properties are unchanged
            assert(pre.valid_idx(i));
            assert(pre.clients.index(i).is_Idle() == post.clients.index(i).is_Idle());
            assert(pre.slots.index(i) == post.slots.index(i));
            // Since not_waiting_inv holds for pre, it holds for post
            assert(!pre.slots.index(i));
        }
    }

    // Proof that waiting_inv holds in post
    assert forall |i: nat| #[trigger] post.client_waiting(i) implies
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        if i == j {
            // Client j is waiting and we just deposited a response for it
            assert(post.response_stored(i));
        } else {
            // Other waiting clients are unchanged
            assert(pre.client_waiting(i) == post.client_waiting(i));
            assert(pre.request_stored(i) == post.request_stored(i));
            assert(pre.response_stored(i) == post.response_stored(i));
            assert(pre.combiner_has(i) == post.combiner_has(i));
            // Since waiting_inv holds for pre, it holds for post
            assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
        }
    }

    // Proof that request_stored_inv holds in post
    assert forall |i: nat| #[trigger] post.request_stored(i) implies
        post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i) by {
        // No requests were added or removed in this transition, only responses
        assert(pre.request_stored(i));
        assert(pre.client_waiting(i));
        assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(pre.slots.index(i));
        // These properties carry over to post since requests are unchanged
        assert(post.client_waiting(i));
        assert(post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid());
        assert(post.slots.index(i));
    }

    // Proof that response_stored_inv holds in post
    assert forall |i: nat| #[trigger] post.response_stored(i) implies
        post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i) by {
        if i == j {
            // This is the newly stored response
            assert(post.client_waiting(i));
            assert(post.responses.index(i).rid == response.rid);
            // From the precondition: response_opt == Option::Some(response.rid)
            // And from combiner_has_inv in pre: pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid()
            // So: response.rid == pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid()
            assert(post.clients.index(i).get_Waiting_rid() == response.rid);
            assert(post.slots.index(i) == false); // We just set it to false
        } else {
            // Other stored responses are unchanged
            assert(pre.response_stored(i));
            assert(pre.client_waiting(i));
            assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
            assert(!pre.slots.index(i));
            // These properties carry over to post
            assert(post.client_waiting(i));
            assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
            assert(!post.slots.index(i));
        }
    }
}

